def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    rejected = []
    history = []

    def parse_amount(token):
        if not token or any(c < "0" or c > "9" for c in token):
            return None
        value = 0
        for start in range(0, len(token), 9):
            chunk = token[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        if not parts or any(not part for part in parts):
            rejected.append(index)
            continue

        verb = parts[0]

        if verb == "undo" and len(parts) == 1:
            if not history:
                rejected.append(index)
                continue
            entry = history.pop()
            if entry[0] == "open":
                del balances[entry[1]]
                frozen.discard(entry[1])
            else:
                for account, balance, was_frozen in entry[1]:
                    balances[account] = balance
                    if was_frozen:
                        frozen.add(account)
                    else:
                        frozen.discard(account)

        elif verb in ("open", "deposit", "withdraw") and len(parts) == 3:
            account = parts[1]
            amount = parse_amount(parts[2])
            if amount is None:
                rejected.append(index)
                continue

            if verb == "open":
                if account in balances:
                    rejected.append(index)
                    continue
                balances[account] = amount
                history.append(("open", account))
            else:
                if (
                    amount == 0
                    or account not in balances
                    or (
                        verb == "withdraw"
                        and (account in frozen or balances[account] < amount)
                    )
                ):
                    rejected.append(index)
                    continue
                history.append(("restore", [(account, balances[account], account in frozen)]))
                if verb == "deposit":
                    balances[account] += amount
                else:
                    balances[account] -= amount

        elif verb == "transfer" and len(parts) == 4:
            source, destination = parts[1], parts[2]
            amount = parse_amount(parts[3])
            if (
                amount is None
                or amount == 0
                or source == destination
                or source not in balances
                or destination not in balances
                or source in frozen
                or balances[source] < amount
            ):
                rejected.append(index)
                continue
            history.append(
                (
                    "restore",
                    [
                        (source, balances[source], source in frozen),
                        (destination, balances[destination], destination in frozen),
                    ],
                )
            )
            balances[source] -= amount
            balances[destination] += amount

        elif verb in ("freeze", "unfreeze") and len(parts) == 2:
            account = parts[1]
            if (
                account not in balances
                or (verb == "freeze" and account in frozen)
                or (verb == "unfreeze" and account not in frozen)
            ):
                rejected.append(index)
                continue
            history.append(("restore", [(account, balances[account], account in frozen)]))
            if verb == "freeze":
                frozen.add(account)
            else:
                frozen.remove(account)

        else:
            rejected.append(index)

    return balances, rejected
